const app = document.querySelector('#app');
const modalRoot = document.querySelector('#modal-root');
const toastRoot = document.querySelector('#toast-root');

const state = {
  token: localStorage.getItem('novabank_token'),
  me: null,
  view: 'overview',
  cache: {},
  authMode: 'login',
  mfaChallenge: null,
  rememberDevice: false,
};

const customerNav = [
  ['overview','⌂','Overview'],['accounts','◫','Accounts'],['transfers','⇄','Transfers'],['beneficiaries','◎','Beneficiaries'],
  ['transactions','≡','Transactions'],['statements','▤','Statements'],['cards','▰','Cards'],['bills','⌁','Bills & payments'],
  ['loans','◇','Loans'],['kyc','✓','KYC & profile'],['notifications','●','Notifications'],['security','⚿','Security']
];
/*
 * The fourth element is what the view's own list endpoint requires, taken from
 * the guard on each admin route rather than invented here. 'role:ADMIN' marks
 * the two endpoints guarded by requireAdmin instead of a permission.
 *
 * Filtering this against the permissions /api/me reports means the sidebar and
 * the server read the same table, so an entry cannot be offered to a role the
 * server will refuse. (BUG-UI-002)
 */
const adminNav = [
  ['admin-dashboard','⌂','Operations','READ_CUSTOMERS'],['admin-customers','◉','Customers','READ_CUSTOMERS'],
  ['admin-kyc','✓','KYC review','READ_CUSTOMERS'],['admin-accounts','◫','Accounts','READ_ACCOUNTS'],
  ['admin-transfers','⇄','Transfers','READ_TRANSFERS'],['admin-loans','◇','Loans','READ_CUSTOMERS'],
  ['admin-fraud','⚑','Fraud alerts','READ_FRAUD'],['admin-audit','≣','Audit logs','READ_AUDIT'],
  ['admin-users','♙','Users & roles','role:ADMIN']
];

/*
 * A convenience, never the authorization: every one of these endpoints still
 * enforces its own guard. This only stops the interface offering an action
 * that is certain to fail.
 */
function navAllowed(entry){
  const need=entry[3];
  if(!need)return true;
  if(need.startsWith('role:'))return state.me?.user?.role===need.slice(5);
  return (state.me?.permissions||[]).includes(need);
}

function navFor(role){return staffRoles.has(role)?adminNav.filter(navAllowed):customerNav;}
const staffRoles = new Set(['ADMIN','MANAGER','SUPPORT','AUDITOR','EMPLOYEE']);

function escapeHtml(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function money(minor,currency='EGP'){return new Intl.NumberFormat('en-EG',{style:'currency',currency,maximumFractionDigits:2}).format((Number(minor)||0)/100);}
function date(v){if(!v)return '—';return new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));}
function statusBadge(status){const s=String(status||'UNKNOWN');const good=['ACTIVE','COMPLETED','VERIFIED','APPROVED','PAID','CLEARED'].includes(s);const bad=['FAILED','REJECTED','CANCELLED','CLOSED','SUSPENDED','CONFIRMED'].includes(s);const warn=['PENDING','PROCESSING','UNDER_REVIEW','SUBMITTED','NEEDS_MORE_INFORMATION','FROZEN','PENDING_ACTIVATION','OPEN','INVESTIGATING','SCHEDULED'].includes(s);return `<span class="badge ${good?'good':bad?'bad':warn?'warn':'info'}"><span class="status-dot"></span>${escapeHtml(s.replaceAll('_',' '))}</span>`;}
function mask(v=''){v=String(v);return v.length>4?`•••• ${v.slice(-4)}`:v;}
function idKey(){return `web-${Date.now()}-${crypto.randomUUID()}`;}
function fileToBase64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]||'');r.onerror=reject;r.readAsDataURL(file);});}

async function api(path, options={}){
  const headers={'Content-Type':'application/json',...(options.headers||{})};
  if(state.token) headers.Authorization=`Bearer ${state.token}`;
  const res=await fetch(path,{...options,headers});
  const type=res.headers.get('content-type')||'';
  const data=type.includes('application/json')?await res.json():await res.text();
  if(!res.ok){
    if(res.status===401 && !path.startsWith('/api/auth/')) logout(false);
    throw Object.assign(new Error(data?.error||data||`Request failed (${res.status})`),{status:res.status,data});
  }
  return data;
}
function toast(title,message='',kind=''){toastRoot.innerHTML=`<div class="toast ${kind}" data-testid="toast"><strong>${escapeHtml(title)}</strong>${escapeHtml(message)}</div>`;setTimeout(()=>{toastRoot.innerHTML='';},3800);}
function openModal(title,content,{large=false,footer=''}={}){modalRoot.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this) closeModal()"><div class="modal ${large?'large':''}" data-testid="modal"><div class="modal-head"><div><h2>${escapeHtml(title)}</h2></div><button class="close" onclick="closeModal()" data-testid="modal-close">×</button></div>${content}${footer?`<div class="modal-footer">${footer}</div>`:''}</div></div>`;}
window.closeModal=()=>{modalRoot.innerHTML='';};

function authTemplate(){
  app.innerHTML=`<div class="auth-shell">
    <section class="auth-hero">
      <div class="brand"><div class="brand-mark">N</div><span>NovaBank <span class="muted">QA Lab</span></span></div>
      <div class="hero-copy"><div class="badge good">FULL-STACK BANKING SIMULATION</div><h1>Banking built to be <span>tested.</span></h1><p>A controlled retail banking platform with real state transitions, transactional money movement, KYC, RBAC, audit trails, fraud rules and deterministic failure paths—built specifically for software quality engineering.</p><div class="hero-pills"><span class="pill">Customer banking</span><span class="pill">Back-office operations</span><span class="pill">REST API</span><span class="pill">Relational ledger</span><span class="pill">QA fault injection</span></div></div>
      <div class="small muted">Simulated financial environment • No real money, cards or external banking rails</div>
    </section>
    <section class="auth-panel"><div class="auth-card" id="auth-card"></div></section>
  </div>`;
  renderAuthCard();
}
function renderAuthCard(){
  const c=document.querySelector('#auth-card'); if(!c)return;
  if(state.mfaChallenge){
    c.innerHTML=`<h2>Two-factor verification</h2><p class="muted">Enter the one-time code to complete sign in.</p><form id="mfa-form" data-testid="mfa-form"><div class="field"><label>6-digit code</label><input name="code" inputmode="numeric" maxlength="6" value="123456" data-testid="mfa-code" required></div><div class="callout">QA mode: the seeded OTP is <b class="mono">123456</b>.</div><button class="btn primary full" type="submit" style="margin-top:16px" data-testid="mfa-submit">Verify & sign in</button></form><button class="link-btn" style="margin-top:15px" onclick="cancelMfa()" data-testid="mfa-cancel">Back to login</button>`;
    document.querySelector('#mfa-form').onsubmit=submitMfa;return;
  }
  const login=state.authMode==='login';
  c.innerHTML=`<h2>${login?'Welcome back':'Create customer profile'}</h2><p class="muted">${login?'Sign in to the NovaBank testing environment.':'Register a new simulated retail banking customer.'}</p>
    <div class="auth-tabs"><button class="${login?'active':''}" onclick="setAuthMode('login')" data-testid="tab-login">Sign in</button><button class="${!login?'active':''}" onclick="setAuthMode('register')" data-testid="tab-register">Register</button></div>
    ${login?`<form id="login-form" data-testid="login-form"><div class="field"><label>Email</label><input name="email" type="email" value="customer@novabank.test" data-testid="login-email" required></div><div class="field"><label>Password</label><input name="password" type="password" value="Demo123!" data-testid="login-password" required></div><label class="small muted"><input type="checkbox" name="remember"> Remember this device</label><button class="btn primary full" type="submit" data-testid="login-submit" style="margin-top:16px">Continue</button></form><div class="auth-help"><button class="link-btn" onclick="forgotPassword()" data-testid="forgot-password">Forgot password?</button><span class="small muted">MFA enabled</span></div>`:`<form id="register-form" data-testid="register-form"><div class="grid-2"><div class="field"><label>First name</label><input name="firstName" required></div><div class="field"><label>Last name</label><input name="lastName" required></div></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Phone</label><input name="phone" value="+20 "></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" required></div><button class="btn primary full" type="submit">Create account</button></form>`}
    <details class="demo-credentials"><summary>Seeded QA credentials</summary><div class="cred-grid"><div class="cred"><b>Customer</b>customer@novabank.test<br>Demo123!</div><div class="cred"><b>Admin</b>admin@novabank.test<br>Admin123!</div><div class="cred"><b>Manager</b>manager@novabank.test<br>Manager123!</div><div class="cred"><b>Auditor</b>auditor@novabank.test<br>Auditor123!</div><div class="cred"><b>Support</b>support@novabank.test<br>Support123!</div><div class="cred"><b>Employee</b>employee@novabank.test<br>Employee123!</div></div><div class="small muted" style="margin-top:8px">Seeded MFA code: <span class="mono">123456</span></div></details>`;
  if(login)document.querySelector('#login-form').onsubmit=submitLogin;else document.querySelector('#register-form').onsubmit=submitRegister;
}
window.setAuthMode=(m)=>{state.authMode=m;renderAuthCard();};window.cancelMfa=()=>{state.mfaChallenge=null;renderAuthCard();};
async function submitLogin(e){e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password'),rememberDevice:!!f.get('remember')})});if(r.mfaRequired){state.mfaChallenge=r.challenge;state.rememberDevice=!!f.get('remember');renderAuthCard();toast('MFA required',r.demoCode?`QA code: ${r.demoCode}`:'Check your authenticator.');}else finishLogin(r);}catch(err){toast('Sign in failed',err.message,'error');}}
async function submitMfa(e){e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await api('/api/auth/mfa',{method:'POST',body:JSON.stringify({challenge:state.mfaChallenge,code:f.get('code'),rememberDevice:state.rememberDevice})});state.mfaChallenge=null;finishLogin(r);}catch(err){toast('Verification failed',err.message,'error');}}
function finishLogin(r){state.token=r.token;localStorage.setItem('novabank_token',r.token);bootstrap();}
async function submitRegister(e){e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await api('/api/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});openModal('Verify email',`<p class="muted">Enter the verification code issued by the simulated email service.</p><form id="verify-form"><div class="field"><label>Verification code</label><input name="code" value="${r.demoVerificationCode||''}" required></div><button class="btn primary full">Verify email</button></form>`);document.querySelector('#verify-form').onsubmit=async ev=>{ev.preventDefault();const code=new FormData(ev.currentTarget).get('code');try{await api('/api/auth/verify-email',{method:'POST',body:JSON.stringify({code})});closeModal();toast('Email verified','You can now sign in.');state.authMode='login';renderAuthCard();}catch(err){toast('Verification failed',err.message,'error');}};}catch(err){toast('Registration failed',err.message,'error');}}
window.forgotPassword=async()=>{openModal('Reset password',`<form id="forgot-form"><p class="muted">A simulated reset token will be returned in QA mode.</p><div class="field"><label>Email</label><input name="email" type="email" value="customer@novabank.test" data-testid="login-email" required></div><button class="btn primary full">Issue reset token</button></form><div id="reset-stage"></div>`);document.querySelector('#forgot-form').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/auth/forgot-password',{method:'POST',body:JSON.stringify({email:new FormData(e.currentTarget).get('email')})});document.querySelector('#reset-stage').innerHTML=`<form id="reset-form"><div class="field"><label>Reset token</label><input name="token" value="${r.demoResetToken||''}" required></div><div class="field"><label>New password</label><input name="password" type="password" minlength="8" required></div><button class="btn primary full">Reset password</button></form>`;document.querySelector('#reset-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);try{await api('/api/auth/reset-password',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});closeModal();toast('Password reset','Sign in using the new password.');}catch(err){toast('Reset failed',err.message,'error');}};}catch(err){toast('Request failed',err.message,'error');}};};
function logout(callApi=true){if(callApi&&state.token)api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.token=null;state.me=null;state.cache={};localStorage.removeItem('novabank_token');authTemplate();}
window.logout=logout;

async function bootstrap(){
  if(!state.token){authTemplate();return;}
  try{state.me=await api('/api/me');state.view=staffRoles.has(state.me.user.role)?'admin-dashboard':'overview';renderShell();await navigate(state.view);}catch{logout(false);}
}
function renderShell(){
  const u=state.me.user,staff=staffRoles.has(u.role),nav=navFor(u.role);
  app.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">N</div><span>NovaBank</span></div><div class="nav-group"><div class="nav-label">${staff?'Back office':'Banking'}</div>${nav.map(([id,ic,label])=>`<button class="nav-btn" data-view="${id}" data-testid="nav-${id}" onclick="navigate('${id}')"><span class="nav-icon">${ic}</span><span class="nav-text">${label}</span></button>`).join('')}</div><div class="sidebar-bottom"><div class="user-chip" data-testid="user-chip"><b>${escapeHtml(u.first_name)} ${escapeHtml(u.last_name)}</b><span>${escapeHtml(u.role.replaceAll('_',' '))}</span></div><button class="nav-btn" onclick="logout()" data-testid="logout"><span class="nav-icon">↪</span><span class="nav-text">Sign out</span></button></div></aside><main class="content"><div class="topbar"><div><div class="small muted" id="eyebrow">NOVABANK</div><h1 id="page-title" data-testid="page-title">Loading…</h1></div><div class="top-actions"><span class="badge info" data-testid="user-role">${escapeHtml(u.role)}</span>${!staff?`<button class="btn" onclick="navigate('notifications')">Notifications <span id="unread-count" data-testid="unread-count">${state.me.unreadNotifications||0}</span></button>`:''}</div></div><div id="view" data-testid="view"></div></main></div>`;
}
window.navigate=navigate;
async function navigate(view){state.view=view;document.querySelectorAll('.nav-btn[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));const title=(staffRoles.has(state.me.user.role)?adminNav:customerNav).find(x=>x[0]===view)?.[2]||'NovaBank';document.querySelector('#page-title').textContent=title;document.querySelector('#eyebrow').textContent=staffRoles.has(state.me.user.role)?'BACK-OFFICE OPERATIONS':'DIGITAL BANKING';const root=document.querySelector('#view');root.innerHTML='<div class="empty">Loading…</div>';try{const renderers={overview:renderOverview,accounts:renderAccounts,transfers:renderTransfers,beneficiaries:renderBeneficiaries,transactions:renderTransactions,statements:renderStatements,cards:renderCards,bills:renderBills,loans:renderLoans,kyc:renderKyc,notifications:renderNotifications,security:renderSecurity,'admin-dashboard':renderAdminDashboard,'admin-customers':renderAdminCustomers,'admin-kyc':renderAdminKyc,'admin-accounts':renderAdminAccounts,'admin-transfers':renderAdminTransfers,'admin-loans':renderAdminLoans,'admin-fraud':renderAdminFraud,'admin-audit':renderAdminAudit,'admin-users':renderAdminUsers};await renderers[view]?.(root);}catch(err){root.innerHTML=`<div class="callout danger"><b>Unable to load this module.</b><br>${escapeHtml(err.message)}</div>`;}}

async function refreshMe(){state.me=await api('/api/me');const unread=document.querySelector('#unread-count');if(unread)unread.textContent=state.me.unreadNotifications||0;}
function accountCard(a){return `<div class="account-card" data-testid="account-card" data-account-id="${a.id}"><div class="split"><div class="account-type" data-testid="account-type">${a.account_type} • ${a.currency}</div>${statusBadge(a.status)}</div><div class="balance" data-testid="account-balance" data-balance-minor="${a.balance_minor}">${money(a.balance_minor,a.currency)}</div><div class="small muted" data-testid="account-available" data-available-minor="${a.available_minor}">Available ${money(a.available_minor,a.currency)}</div><div class="account-meta mono">${mask(a.account_number)} • ${escapeHtml(a.iban.slice(0,8))}…${escapeHtml(a.iban.slice(-6))}</div><div class="account-actions"><button class="btn small-btn" onclick="viewAccountTransactions(${a.id})">Activity</button><button class="btn small-btn ghost" onclick="openStatementFor(${a.id})">Statement</button></div></div>`;}
/*
 * The customer dashboard, covering DASH-001 to DASH-007.
 *
 * Recent transactions, active cards and upcoming scheduled payments were
 * required by the catalog but never rendered here, which is why the module had
 * no automated coverage: there was nothing to assert against. Recorded as
 * BUG-DASH-001 and fixed by this function.
 *
 * Transactions are read per account and merged, rather than through a new
 * aggregate endpoint, so the dashboard adds no API surface of its own.
 */
async function renderOverview(root){
  await refreshMe();
  const accounts=state.me.accounts;
  const egpTotal=accounts.filter(a=>a.currency==='EGP').reduce((s,a)=>s+a.balance_minor,0);
  const [transfers,notifications,billPayments,txLists]=await Promise.all([
    api('/api/transfers').catch(()=>[]),
    api('/api/notifications').catch(()=>[]),
    api('/api/bill-payments').catch(()=>[]),
    Promise.all(accounts.slice(0,5).map(a=>api(`/api/accounts/${a.id}/transactions`).catch(()=>[])))
  ]);
  const recentTx=txLists.flat().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,5);
  const activeCards=(state.me.cards||[]).filter(c=>c.status==='ACTIVE');
  const now=new Date().toISOString();
  const upcoming=[
    ...billPayments.filter(b=>b.scheduled_for&&b.scheduled_for>now&&b.status!=='CANCELLED').map(b=>({when:b.scheduled_for,label:b.customer_reference||'Bill payment',amount:b.amount_minor,currency:'EGP',kind:'BILL'})),
    ...transfers.filter(t=>t.scheduled_for&&t.scheduled_for>now&&t.status==='SCHEDULED').map(t=>({when:t.scheduled_for,label:t.memo||t.reference,amount:t.amount_minor,currency:t.source_currency||'EGP',kind:'TRANSFER'}))
  ].sort((a,b)=>String(a.when).localeCompare(String(b.when))).slice(0,5);
  /*
   * The authoritative unread count comes from /api/me, which counts rows in
   * the database. /api/notifications is capped at 200, so counting the page
   * would under-report as soon as a customer passes that -- and would
   * disagree with the badge in the topbar, which reads the same field.
   */
  const unreadCount=Number(state.me.unreadNotifications||0);
  root.innerHTML=`<div class="hero-card"><div class="badge good">SECURE QA ENVIRONMENT</div><h2 data-testid="overview-greeting">Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${escapeHtml(state.me.user.first_name)}.</h2><p>Your banking environment is live. Every operation below creates real application state, ledger entries, notifications and audit records for testing.</p></div><div class="kpi-grid"><div class="card kpi" data-testid="kpi-egp-balance" data-balance-minor="${egpTotal}"><div class="label">EGP balance</div><div class="value">${money(egpTotal,'EGP')}</div><div class="sub">Across active and frozen EGP accounts</div></div><div class="card kpi" data-testid="kpi-accounts"><div class="label">Accounts</div><div class="value" data-testid="kpi-accounts-value">${accounts.length}</div><div class="sub">${accounts.filter(a=>a.status==='ACTIVE').length} active</div></div><div class="card kpi" data-testid="kpi-transfers"><div class="label">Transfers</div><div class="value">${transfers.length}</div><div class="sub">${transfers.filter(t=>t.status==='COMPLETED').length} completed</div></div><div class="card kpi" data-testid="kpi-kyc"><div class="label">KYC status</div><div class="value" style="font-size:18px;margin-top:12px">${statusBadge(state.me.kyc?.status||'NOT_STARTED')}</div><div class="sub">Identity &amp; compliance profile</div></div></div><div class="section-grid"><div class="card" data-testid="overview-accounts"><div class="section-head"><h2>Your accounts</h2><button class="btn small-btn" onclick="navigate('accounts')">Manage</button></div><div class="account-grid">${accounts.slice(0,3).map(accountCard).join('')||'<div class="empty" data-testid="overview-accounts-empty">No accounts yet.</div>'}</div></div><div class="card" data-testid="overview-alerts"><div class="section-head"><div><h2>Recent alerts</h2><p class="small muted"><span data-testid="overview-unread-count">${unreadCount}</span> unread</p></div><button class="btn small-btn" onclick="navigate('notifications')">All</button></div><div class="list">${notifications.slice(0,5).map(n=>`<div class="list-item notification ${n.read_at?'':'unread'}" data-testid="overview-alert-item" data-unread="${n.read_at?'false':'true'}"><div><div class="title">${escapeHtml(n.title)}</div><div class="meta">${escapeHtml(n.message)}</div></div><span class="small muted nowrap">${date(n.created_at)}</span></div>`).join('')||'<div class="empty" data-testid="overview-alerts-empty">No notifications.</div>'}</div></div></div><div class="section-grid"><div class="card" data-testid="overview-transactions"><div class="section-head"><div><h2>Recent transactions</h2><p class="small muted">Across your accounts</p></div><button class="btn small-btn" onclick="navigate('transactions')">All</button></div><div class="list">${recentTx.map(t=>`<div class="list-item" data-testid="overview-transaction-row" data-direction="${escapeHtml(t.direction)}" data-amount-minor="${t.amount_minor}"><div><div class="title">${escapeHtml(t.description)}</div><div class="meta mono">${escapeHtml(t.reference)} &bull; ${escapeHtml(t.transaction_type)}</div></div><span class="nowrap ${t.direction==='CREDIT'?'good':'danger'}">${t.direction==='CREDIT'?'+':'-'}${money(t.amount_minor,t.currency)}</span></div>`).join('')||'<div class="empty" data-testid="overview-transactions-empty">No transactions yet.</div>'}</div></div><div class="card" data-testid="overview-cards"><div class="section-head"><div><h2>Active cards</h2><p class="small muted"><span data-testid="overview-cards-count">${activeCards.length}</span> active</p></div><button class="btn small-btn" onclick="navigate('cards')">Manage</button></div><div class="list">${activeCards.slice(0,4).map(c=>`<div class="list-item" data-testid="overview-card-item" data-last4="${escapeHtml(c.last4)}"><div><div class="title mono">&bull;&bull;&bull;&bull; ${escapeHtml(c.last4)}</div><div class="meta">${escapeHtml(c.card_type)} &bull; expires ${String(c.expiry_month).padStart(2,'0')}/${c.expiry_year}</div></div>${statusBadge(c.status)}</div>`).join('')||'<div class="empty" data-testid="overview-cards-empty">No active cards.</div>'}</div></div></div><div class="card" data-testid="overview-scheduled" style="margin-top:16px"><div class="section-head"><div><h2>Upcoming scheduled payments</h2><p class="small muted"><span data-testid="overview-scheduled-count">${upcoming.length}</span> upcoming</p></div><button class="btn small-btn" onclick="navigate('bills')">Bills</button></div><div class="list">${upcoming.map(u=>`<div class="list-item" data-testid="overview-scheduled-item" data-kind="${u.kind}" data-when="${escapeHtml(u.when)}"><div><div class="title">${escapeHtml(u.label)}</div><div class="meta">${u.kind==='BILL'?'Bill payment':'Transfer'} &bull; ${date(u.when)}</div></div><span class="nowrap">${money(u.amount,u.currency)}</span></div>`).join('')||'<div class="empty" data-testid="overview-scheduled-empty">No upcoming scheduled payments.</div>'}</div></div>`;
}

async function renderAccounts(root){await refreshMe();root.innerHTML=`<div class="section-head"><div><h2>Accounts</h2><p class="small muted">Current, savings and multi-currency accounts.</p></div><button class="btn primary" onclick="openAccountModal()" data-testid="open-account">Open account</button></div><div class="account-grid">${state.me.accounts.map(accountCard).join('')}</div><div class="card" style="margin-top:16px"><div class="section-head"><h3>Account controls</h3></div><div class="callout warn">Freezing an account immediately blocks outgoing transfers and payments. Closing an account requires a zero balance and is permanent in the demo workflow.</div><div class="table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>Account</th><th>Type</th><th>Currency</th><th>Balance</th><th>Daily limit</th><th>Status</th><th></th></tr></thead><tbody>${state.me.accounts.map(a=>`<tr><td class="mono">${mask(a.account_number)}</td><td>${a.account_type}</td><td>${a.currency}</td><td>${money(a.balance_minor,a.currency)}</td><td>${money(a.daily_limit_minor,a.currency)}</td><td>${statusBadge(a.status)}</td><td class="right">${a.status==='ACTIVE'?`<button class="btn small-btn warn" onclick="freezeAccount(${a.id})">Freeze</button>`:''} ${a.status!=='CLOSED'?`<button class="btn small-btn danger" onclick="closeAccount(${a.id})">Close</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`;}
window.openAccountModal=()=>{openModal('Open a new account',`<form id="account-form"><div class="grid-2"><div class="field"><label>Account type</label><select name="accountType"><option>CURRENT</option><option selected>SAVINGS</option></select></div><div class="field"><label>Currency</label><select name="currency"><option>EGP</option><option>USD</option><option>EUR</option><option>GBP</option></select></div></div><div class="callout">KYC must be VERIFIED. New accounts open with a zero balance.</div><button class="btn primary full" style="margin-top:14px" data-testid="account-open-submit">Open account</button></form>`);setTimeout(()=>{const f=document.querySelector('#account-form');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{await api('/api/accounts',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();toast('Account opened','The new account is ready.');renderAccounts(document.querySelector('#view'));}catch(err){toast('Unable to open account',err.message,'error');}}},0);};
window.freezeAccount=async id=>{if(!confirm('Freeze this account? Outgoing transactions will be blocked.'))return;try{await api(`/api/accounts/${id}/freeze`,{method:'POST',body:'{}'});toast('Account frozen');renderAccounts(document.querySelector('#view'));}catch(e){toast('Action failed',e.message,'error');}};
window.closeAccount=async id=>{if(!confirm('Close this account permanently? Its balance must be zero.'))return;try{await api(`/api/accounts/${id}/close`,{method:'POST',body:'{}'});toast('Account closed');renderAccounts(document.querySelector('#view'));}catch(e){toast('Action failed',e.message,'error');}};
window.viewAccountTransactions=id=>{state.cache.selectedAccount=id;navigate('transactions');};window.openStatementFor=id=>{state.cache.statementAccount=id;navigate('statements');};

async function renderTransfers(root){const [accounts,bens,transfers]=await Promise.all([api('/api/accounts'),api('/api/beneficiaries'),api('/api/transfers')]);root.innerHTML=`<div class="section-head"><div><h2>Move money</h2><p class="small muted">Own-account, same-bank and simulated external transfers.</p></div><button class="btn primary" onclick="openTransferModal()" data-testid="new-transfer">New transfer</button></div><div class="card"><div class="callout">Transfers enforce available balance, account status, beneficiary verification, daily limits and idempotency. Same-bank transfers credit both ledgers atomically.</div></div><div class="card" style="margin-top:16px"><div class="section-head"><h3>Transfer history</h3><span class="small muted">${transfers.length} records</span></div>${tableTransfers(transfers,false)}</div>`;state.cache.transferAccounts=accounts;state.cache.transferBeneficiaries=bens;}
function tableTransfers(rows,admin){return rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Reference</th>${admin?'<th>Customer</th>':''}<th>Type</th><th>Destination</th><th>Amount</th><th>Fee</th><th>Status</th><th>Date</th>${admin?'<th></th>':''}</tr></thead><tbody>${rows.map(t=>`<tr><td class="mono">${escapeHtml(t.reference)}</td>${admin?`<td>${escapeHtml(t.email||'')}</td>`:''}<td>${escapeHtml(t.transfer_type)}</td><td>${escapeHtml(t.beneficiary_name|| (t.to_account_id?`Account #${t.to_account_id}`:'—'))}</td><td>${money(t.amount_minor,t.source_currency)}</td><td>${money(t.fee_minor,t.source_currency)}</td><td>${statusBadge(t.status)}</td><td>${date(t.created_at)}</td>${admin?`<td>${t.status==='COMPLETED'?`<button class="btn small-btn warn" onclick="adminReverseTransfer(${t.id})">Reverse</button>`:''}</td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">No transfers yet.</div>';}
window.openTransferModal=()=>{const accounts=state.cache.transferAccounts||[],bens=(state.cache.transferBeneficiaries||[]).filter(b=>b.status==='ACTIVE');openModal('Create transfer',`<form id="transfer-form" data-testid="transfer-form"><div class="field"><label>From account</label><select name="fromAccountId" data-testid="transfer-from">${accounts.filter(a=>a.status==='ACTIVE').map(a=>`<option value="${a.id}">${a.account_type} ${mask(a.account_number)} — ${money(a.balance_minor,a.currency)}</option>`).join('')}</select></div><div class="field"><label>Destination type</label><select name="destinationType" id="dest-type" data-testid="transfer-dest-type"><option value="beneficiary">Beneficiary</option><option value="own">My account</option></select></div><div class="field" id="beneficiary-field"><label>Beneficiary</label><select name="beneficiaryId" data-testid="transfer-beneficiary">${bens.map(b=>`<option value="${b.id}">${escapeHtml(b.nickname||b.name)} — ${escapeHtml(b.bank_name)} ${b.verified?'✓':'(unverified)'}</option>`).join('')}</select></div><div class="field hidden" id="own-field"><label>Destination account</label><select name="toOwnAccountId" data-testid="transfer-own-account">${accounts.filter(a=>a.status==='ACTIVE').map(a=>`<option value="${a.id}">${a.account_type} ${mask(a.account_number)} • ${a.currency}</option>`).join('')}</select></div><div class="grid-2"><div class="field"><label>Amount</label><input name="amount" type="number" min="0.01" step="0.01" data-testid="transfer-amount" required></div><div class="field"><label>Schedule for (optional)</label><input name="scheduleFor" type="datetime-local"></div></div><div class="field"><label>Memo</label><input name="memo" maxlength="80" data-testid="transfer-memo"></div><details class="demo-credentials"><summary>QA simulation</summary><div class="field"><label>External network behavior</label><select name="qaSimulation"><option value="">Normal</option><option value="failure">Force safe failure / rollback</option></select></div></details><button class="btn primary full" data-testid="transfer-submit">Review & submit</button></form>`);setTimeout(()=>{const type=document.querySelector('#dest-type');type.onchange=()=>{document.querySelector('#beneficiary-field').classList.toggle('hidden',type.value!=='beneficiary');document.querySelector('#own-field').classList.toggle('hidden',type.value!=='own');};document.querySelector('#transfer-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));if(f.destinationType==='own')f.beneficiaryId=null;else f.toOwnAccountId=null;if(f.scheduleFor)f.scheduleFor=new Date(f.scheduleFor).toISOString();f.idempotencyKey=idKey();try{const r=await api('/api/transfers',{method:'POST',body:JSON.stringify(f)});closeModal();toast(r.status==='FAILED'?'Transfer safely failed':'Transfer submitted',r.reference,r.status==='FAILED'?'error':'');renderTransfers(document.querySelector('#view'));}catch(err){toast('Transfer rejected',err.message,'error');}};},0);};

async function renderBeneficiaries(root){const rows=await api('/api/beneficiaries');state.cache.beneficiaries=rows;root.innerHTML=`<div class="section-head"><div><h2>Beneficiaries</h2><p class="small muted">Saved domestic and external recipients.</p></div><button class="btn primary" onclick="openBeneficiaryModal()" data-testid="new-beneficiary">Add beneficiary</button></div><div class="card"><div class="filters"><input id="beneficiary-search" placeholder="Search name, bank or account" oninput="filterBeneficiaries()"></div>${rows.length?`<div class="table-wrap"><table class="table" id="beneficiary-table" data-testid="beneficiary-table"><thead><tr><th>Name</th><th>Bank</th><th>Account / IBAN</th><th>Currency</th><th>Verification</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(b=>`<tr data-search="${escapeHtml(`${b.name} ${b.nickname||''} ${b.bank_name} ${b.account_identifier}`.toLowerCase())}"><td><b>${escapeHtml(b.name)}</b><br><span class="muted small">${escapeHtml(b.nickname||'')}</span></td><td>${escapeHtml(b.bank_name)}</td><td class="mono">${escapeHtml(b.account_identifier)}</td><td>${b.currency}</td><td>${b.verified?'<span class="badge good">VERIFIED</span>':`<button class="btn small-btn" onclick="verifyBeneficiary(${b.id})">Verify OTP</button>`}</td><td>${statusBadge(b.status)}</td><td class="right"><button class="btn small-btn" onclick="editBeneficiary(${b.id})">Edit</button> <button class="btn small-btn danger" onclick="deleteBeneficiary(${b.id})">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No beneficiaries yet.</div>'}</div>`;}
window.filterBeneficiaries=()=>{const q=(document.querySelector('#beneficiary-search')?.value||'').toLowerCase();document.querySelectorAll('#beneficiary-table tbody tr').forEach(r=>r.classList.toggle('hidden',!r.dataset.search.includes(q)));};
window.editBeneficiary=id=>{const b=(state.cache.beneficiaries||[]).find(x=>x.id===id);if(!b)return;openModal('Edit beneficiary',`<form id="edit-ben"><div class="field"><label>Full name</label><input name="name" value="${escapeHtml(b.name)}" required></div><div class="field"><label>Nickname</label><input name="nickname" value="${escapeHtml(b.nickname||'')}"></div><div class="field"><label>Status</label><select name="status"><option ${b.status==='ACTIVE'?'selected':''}>ACTIVE</option><option ${b.status==='DISABLED'?'selected':''}>DISABLED</option></select></div><div class="callout">Bank and account identifier are immutable after verification. Delete and recreate the beneficiary to change those identity fields.</div><button class="btn primary full" style="margin-top:14px">Save beneficiary</button></form>`);setTimeout(()=>{const f=document.querySelector('#edit-ben');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{await api(`/api/beneficiaries/${id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();toast('Beneficiary updated');renderBeneficiaries(document.querySelector('#view'));}catch(err){toast('Update failed',err.message,'error');}}},0);};
window.openBeneficiaryModal=()=>{openModal('Add beneficiary',`<form id="ben-form"><div class="grid-2"><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Nickname</label><input name="nickname"></div></div><div class="grid-2"><div class="field"><label>Bank</label><select name="bankName"><option>NOVABANK</option><option>NILE EXTERNAL BANK</option><option>CAIRO TEST BANK</option><option>FAILBANK</option></select></div><div class="field"><label>Currency</label><select name="currency"><option>EGP</option><option>USD</option><option>EUR</option><option>GBP</option></select></div></div><div class="field"><label>Account number / IBAN</label><input name="accountIdentifier" required></div><div class="callout">For same-bank testing, use an existing NovaBank account number. New beneficiaries require OTP verification before transfers.</div><button class="btn primary full" style="margin-top:14px" data-testid="beneficiary-submit">Add beneficiary</button></form>`);setTimeout(()=>{const f=document.querySelector('#ben-form');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/beneficiaries',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();toast('Beneficiary added',r.demoOtp?`QA OTP: ${r.demoOtp}`:'');renderBeneficiaries(document.querySelector('#view'));}catch(err){toast('Unable to add beneficiary',err.message,'error');}}},0);};
window.verifyBeneficiary=id=>openModal('Verify beneficiary',`<form id="verify-ben"><div class="field"><label>OTP</label><input name="code" value="123456" maxlength="6" required></div><button class="btn primary full">Verify</button></form>`);window.verifyBeneficiary=((orig)=>id=>{orig(id);setTimeout(()=>{const f=document.querySelector('#verify-ben');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{await api(`/api/beneficiaries/${id}/verify`,{method:'POST',body:JSON.stringify({code:new FormData(e.currentTarget).get('code')})});closeModal();toast('Beneficiary verified');renderBeneficiaries(document.querySelector('#view'));}catch(err){toast('Verification failed',err.message,'error');}}},0);})(window.verifyBeneficiary);
window.deleteBeneficiary=async id=>{if(!confirm('Delete this beneficiary?'))return;try{await api(`/api/beneficiaries/${id}`,{method:'DELETE'});toast('Beneficiary deleted');renderBeneficiaries(document.querySelector('#view'));}catch(e){toast('Delete failed',e.message,'error');}};

async function renderTransactions(root){const accounts=await api('/api/accounts');const selected=Number(state.cache.selectedAccount||accounts[0]?.id);const account=accounts.find(a=>a.id===selected);if(!account){root.innerHTML='<div class="empty">No accounts available.</div>';return;}const q=state.cache.transactionFilters||{};const params=new URLSearchParams(Object.entries(q).filter(([,v])=>v));const tx=await api(`/api/accounts/${account.id}/transactions?${params}`);root.innerHTML=`<div class="section-head"><div><h2>Transaction history</h2><p class="small muted">Search and filter ledger activity by account, date, type, status, reference and amount.</p></div><select class="input" style="max-width:300px" onchange="selectTransactionAccount(this.value)">${accounts.map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${a.account_type} ${mask(a.account_number)} • ${a.currency}</option>`).join('')}</select></div><div class="card"><div class="filters"><input id="tx-ref" placeholder="Reference" value="${escapeHtml(q.reference||'')}"><select id="tx-type"><option value="">All types</option>${['TRANSFER','DEPOSIT','BILL_PAYMENT','LOAN_DISBURSEMENT','LOAN_PAYMENT','REVERSAL'].map(x=>`<option ${q.type===x?'selected':''}>${x}</option>`).join('')}</select><select id="tx-status"><option value="">All statuses</option><option ${q.status==='COMPLETED'?'selected':''}>COMPLETED</option></select><input id="tx-from" type="date" value="${escapeHtml(q.from||'')}"><input id="tx-to" type="date" value="${escapeHtml(q.to||'')}"><input id="tx-min" type="number" step="0.01" placeholder="Min amount" value="${escapeHtml(q.minAmount||'')}"><input id="tx-max" type="number" step="0.01" placeholder="Max amount" value="${escapeHtml(q.maxAmount||'')}"><button class="btn small-btn" onclick="applyTransactionFilters()">Apply</button><button class="btn small-btn ghost" onclick="clearTransactionFilters()">Clear</button></div>${tx.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Reference</th><th>Type</th><th>Description</th><th>Direction</th><th>Amount</th><th>Fee</th><th>Balance</th></tr></thead><tbody>${tx.map(t=>`<tr><td>${date(t.created_at)}</td><td class="mono">${escapeHtml(t.reference)}</td><td>${escapeHtml(t.transaction_type)}</td><td>${escapeHtml(t.description)}</td><td>${t.direction==='CREDIT'?'<span class="badge good">CREDIT</span>':'<span class="badge warn">DEBIT</span>'}</td><td>${money(t.amount_minor,t.currency)}</td><td>${money(t.fee_minor,t.currency)}</td><td>${money(t.balance_after_minor,t.currency)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No transactions match the selected filters.</div>'}</div>`;}
window.applyTransactionFilters=()=>{state.cache.transactionFilters={reference:document.querySelector('#tx-ref').value,type:document.querySelector('#tx-type').value,status:document.querySelector('#tx-status').value,from:document.querySelector('#tx-from').value,to:document.querySelector('#tx-to').value,minAmount:document.querySelector('#tx-min').value,maxAmount:document.querySelector('#tx-max').value};renderTransactions(document.querySelector('#view'));};
window.clearTransactionFilters=()=>{state.cache.transactionFilters={};renderTransactions(document.querySelector('#view'));};
window.selectTransactionAccount=id=>{state.cache.selectedAccount=Number(id);renderTransactions(document.querySelector('#view'));};

async function renderStatements(root){const accounts=await api('/api/accounts');const selected=Number(state.cache.statementAccount||accounts[0]?.id);const account=accounts.find(a=>a.id===selected);if(!account){root.innerHTML='<div class="empty">No accounts.</div>';return;}const now=new Date(),from=new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10),to=now.toISOString().slice(0,10);const s=await api(`/api/accounts/${selected}/statement?from=${from}&to=${to}`);root.innerHTML=`<div class="section-head"><div><h2>Statements</h2><p class="small muted">Monthly or custom-date account statements.</p></div><div class="actions"><button class="btn" onclick="downloadStatementCsv(${selected},'${from}','${to}')">Download CSV</button><button class="btn" onclick="window.print()">Print / PDF</button></div></div><div class="card"><div class="filters"><select onchange="selectStatementAccount(this.value)">${accounts.map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${a.account_type} ${mask(a.account_number)} • ${a.currency}</option>`).join('')}</select><input type="date" id="statement-from" value="${from}"><input type="date" id="statement-to" value="${to}"><button class="btn small-btn" onclick="loadCustomStatement()">Apply</button></div><div id="statement-body">${statementHtml(s)}</div></div>`;state.cache.statementCurrent=selected;}
function statementHtml(s){return `<div class="statement-summary"><div class="mini"><label>Opening</label><strong>${money(s.opening_balance_minor,s.account.currency)}</strong></div><div class="mini"><label>Credits</label><strong>${money(s.credits_minor,s.account.currency)}</strong></div><div class="mini"><label>Debits</label><strong>${money(s.debits_minor,s.account.currency)}</strong></div><div class="mini"><label>Fees</label><strong>${money(s.fees_minor,s.account.currency)}</strong></div><div class="mini"><label>Closing</label><strong>${money(s.closing_balance_minor,s.account.currency)}</strong></div></div>${s.transactions.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Reference</th><th>Description</th><th>Direction</th><th>Amount</th><th>Balance</th></tr></thead><tbody>${s.transactions.map(t=>`<tr><td>${date(t.created_at)}</td><td class="mono">${t.reference}</td><td>${escapeHtml(t.description)}</td><td>${t.direction}</td><td>${money(t.amount_minor,t.currency)}</td><td>${money(t.balance_after_minor,t.currency)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No statement transactions for the selected dates.</div>'}`;}
window.selectStatementAccount=id=>{state.cache.statementAccount=Number(id);renderStatements(document.querySelector('#view'));};window.loadCustomStatement=async()=>{const id=state.cache.statementCurrent,from=document.querySelector('#statement-from').value,to=document.querySelector('#statement-to').value;try{const s=await api(`/api/accounts/${id}/statement?from=${from}&to=${to}`);document.querySelector('#statement-body').innerHTML=statementHtml(s);}catch(e){toast('Statement failed',e.message,'error');}};window.downloadStatementCsv=(id,from,to)=>{const a=document.createElement('a');a.href=`/api/accounts/${id}/statement?from=${from}&to=${to}&format=csv`;a.onclick=e=>{e.preventDefault();fetch(a.href,{headers:{Authorization:`Bearer ${state.token}`}}).then(r=>r.blob()).then(blob=>{const u=URL.createObjectURL(blob),x=document.createElement('a');x.href=u;x.download='novabank-statement.csv';x.click();URL.revokeObjectURL(u);});};a.click();};

async function renderCards(root){const [cards,accounts]=await Promise.all([api('/api/cards'),api('/api/accounts')]);state.cache.cardAccounts=accounts;root.innerHTML=`<div class="section-head"><div><h2>Cards</h2><p class="small muted">Virtual debit-card lifecycle and controls.</p></div><button class="btn primary" onclick="requestCardModal()">Request card</button></div><div class="card-grid">${cards.map(c=>`<div class="bank-card"><div class="split"><div class="card-brand">NOVABANK</div>${statusBadge(c.status)}</div><div><div class="digits">•••• •••• •••• ${c.last4}</div><div class="small muted" style="margin-top:7px">${escapeHtml(c.cardholder_name)} • ${String(c.expiry_month).padStart(2,'0')}/${String(c.expiry_year).slice(-2)}</div></div><div class="actions">${c.status==='PENDING_ACTIVATION'?`<button class="btn small-btn" onclick="cardAction(${c.id},'activate')">Activate</button>`:''}${c.status==='ACTIVE'?`<button class="btn small-btn" onclick="cardAction(${c.id},'freeze')">Freeze</button><button class="btn small-btn" onclick="cardSettings(${c.id})">Settings</button>`:''}${c.status==='FROZEN'?`<button class="btn small-btn" onclick="cardAction(${c.id},'unfreeze')">Unfreeze</button>`:''}${!['CANCELLED','REPLACED'].includes(c.status)?`<button class="btn small-btn" onclick="cardAction(${c.id},'replace')">Replace</button><button class="btn small-btn danger" onclick="cardAction(${c.id},'cancel')">Cancel</button>`:''}</div></div>`).join('')||'<div class="empty">No cards issued.</div>'}</div><div class="card" style="margin-top:16px"><div class="section-head"><h3>Card control matrix</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>Card</th><th>ATM</th><th>Online</th><th>International</th><th>Contactless</th><th>ATM limit</th><th>Purchase limit</th><th>Online limit</th></tr></thead><tbody>${cards.map(c=>`<tr><td>•••• ${c.last4}</td><td>${c.atm_enabled?'ON':'OFF'}</td><td>${c.online_enabled?'ON':'OFF'}</td><td>${c.international_enabled?'ON':'OFF'}</td><td>${c.contactless_enabled?'ON':'OFF'}</td><td>${money(c.atm_limit_minor,'EGP')}</td><td>${money(c.purchase_limit_minor,'EGP')}</td><td>${money(c.online_limit_minor,'EGP')}</td></tr>`).join('')}</tbody></table></div></div>`;state.cache.cards=cards;}
window.requestCardModal=()=>{const accounts=state.cache.cardAccounts||[];openModal('Request debit card',`<form id="card-request"><div class="field"><label>Linked account</label><select name="accountId">${accounts.filter(a=>a.status==='ACTIVE').map(a=>`<option value="${a.id}">${a.account_type} ${mask(a.account_number)} • ${a.currency}</option>`).join('')}</select></div><button class="btn primary full" data-testid="card-request-submit">Request card</button></form>`);setTimeout(()=>{const f=document.querySelector('#card-request');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{await api('/api/cards',{method:'POST',body:JSON.stringify({accountId:Number(new FormData(e.currentTarget).get('accountId'))})});closeModal();toast('Card requested','Activate it from the cards page.');renderCards(document.querySelector('#view'));}catch(err){toast('Request failed',err.message,'error');}}},0);};
window.cardAction=async(id,action)=>{if(['replace','cancel'].includes(action)&&!confirm(`${action} this card?`))return;try{await api(`/api/cards/${id}/${action}`,{method:'POST',body:'{}'});toast('Card updated',action.toUpperCase());renderCards(document.querySelector('#view'));}catch(e){toast('Card action failed',e.message,'error');}};
window.cardSettings=id=>{const c=(state.cache.cards||[]).find(x=>x.id===id);openModal('Card settings',`<form id="card-settings"><div class="grid-2"><label class="field"><span>ATM</span><select name="atmEnabled"><option value="1" ${c.atm_enabled?'selected':''}>Enabled</option><option value="">Disabled</option></select></label><label class="field"><span>Online purchases</span><select name="onlineEnabled"><option value="1" ${c.online_enabled?'selected':''}>Enabled</option><option value="">Disabled</option></select></label><label class="field"><span>International</span><select name="internationalEnabled"><option value="1" ${c.international_enabled?'selected':''}>Enabled</option><option value="">Disabled</option></select></label><label class="field"><span>Contactless</span><select name="contactlessEnabled"><option value="1" ${c.contactless_enabled?'selected':''}>Enabled</option><option value="">Disabled</option></select></label></div><div class="grid-2"><div class="field"><label>ATM daily limit</label><input name="atmLimit" type="number" value="${c.atm_limit_minor/100}"></div><div class="field"><label>Purchase daily limit</label><input name="purchaseLimit" type="number" value="${c.purchase_limit_minor/100}"></div></div><div class="field"><label>Online daily limit</label><input name="onlineLimit" type="number" value="${c.online_limit_minor/100}"></div><button class="btn primary full" data-testid="card-settings-submit">Save settings</button></form>`);setTimeout(()=>{const f=document.querySelector('#card-settings');if(!f)return;f.onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));for(const k of ['atmEnabled','onlineEnabled','internationalEnabled','contactlessEnabled'])f[k]=!!f[k];try{await api(`/api/cards/${id}/settings`,{method:'POST',body:JSON.stringify(f)});closeModal();toast('Card settings saved');renderCards(document.querySelector('#view'));}catch(err){toast('Unable to save',err.message,'error');}}},0);};

async function renderBills(root){const [meta,payments,accounts]=await Promise.all([api('/api/billers'),api('/api/bill-payments'),api('/api/accounts')]);state.cache.billers=meta;state.cache.billAccounts=accounts;root.innerHTML=`<div class="section-head"><div><h2>Bills & payments</h2><p class="small muted">Immediate, scheduled and recurring simulated bill payments.</p></div><div class="actions"><button class="btn" onclick="saveBillerModal()">Save biller</button><button class="btn primary" onclick="payBillModal()">Pay bill</button></div></div><div class="section-grid"><div class="card"><div class="section-head"><h3>Payment history</h3></div>${payments.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Reference</th><th>Biller</th><th>Customer ref</th><th>Amount</th><th>Status</th><th>Schedule</th></tr></thead><tbody>${payments.map(p=>`<tr><td class="mono">${p.reference}</td><td>${escapeHtml(p.biller_name)}</td><td>${escapeHtml(p.customer_reference)}</td><td>${money(p.amount_minor,'EGP')}</td><td>${statusBadge(p.status)}</td><td>${p.scheduled_for?date(p.scheduled_for):'Immediate'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No bill payments yet.</div>'}</div><div class="card"><div class="section-head"><h3>Saved billers</h3></div><div class="list">${meta.saved.map(s=>`<div class="list-item"><div><div class="title">${escapeHtml(s.alias||s.name)}</div><div class="meta">${escapeHtml(s.name)} • ${escapeHtml(s.customer_reference)}</div></div><span class="badge">${escapeHtml(s.category)}</span></div>`).join('')||'<div class="empty">No saved billers.</div>'}</div></div></div>`;}
window.saveBillerModal=()=>{const meta=state.cache.billers;openModal('Save biller',`<form id="save-biller"><div class="field"><label>Biller</label><select name="billerId">${meta.billers.map(b=>`<option value="${b.id}">${escapeHtml(b.name)} — ${escapeHtml(b.category)}</option>`).join('')}</select></div><div class="field"><label>Alias</label><input name="alias" placeholder="Home electricity"></div><div class="field"><label>Customer reference</label><input name="customerReference" required></div><button class="btn primary full">Save biller</button></form>`);setTimeout(()=>{const f=document.querySelector('#save-biller');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{await api('/api/billers/saved',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();toast('Biller saved');renderBills(document.querySelector('#view'));}catch(err){toast('Unable to save biller',err.message,'error');}}},0);};
window.payBillModal=()=>{const meta=state.cache.billers,accounts=state.cache.billAccounts;openModal('Pay a bill',`<form id="pay-bill"><div class="grid-2"><div class="field"><label>From account</label><select name="accountId">${accounts.filter(a=>a.status==='ACTIVE').map(a=>`<option value="${a.id}">${mask(a.account_number)} • ${a.currency} • ${money(a.balance_minor,a.currency)}</option>`).join('')}</select></div><div class="field"><label>Biller</label><select name="billerId">${meta.billers.map(b=>`<option value="${b.id}">${escapeHtml(b.name)}</option>`).join('')}</select></div></div><div class="field"><label>Customer reference</label><input name="customerReference" required></div><div class="grid-2"><div class="field"><label>Amount</label><input name="amount" type="number" min="0.01" step="0.01" data-testid="transfer-amount" required></div><div class="field"><label>Schedule for (optional)</label><input name="scheduleFor" type="datetime-local"></div></div><div class="field"><label>Recurring</label><select name="recurringFrequency"><option value="">One-time</option><option>MONTHLY</option><option>WEEKLY</option></select></div><button class="btn primary full" data-testid="bill-submit">Submit payment</button></form>`);setTimeout(()=>{const f=document.querySelector('#pay-bill');if(!f)return;f.onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));if(f.scheduleFor)f.scheduleFor=new Date(f.scheduleFor).toISOString();try{const r=await api('/api/bill-payments',{method:'POST',body:JSON.stringify(f)});closeModal();toast('Bill payment submitted',r.reference);renderBills(document.querySelector('#view'));}catch(err){toast('Payment failed',err.message,'error');}}},0);};

async function renderLoans(root){const [loans,accounts]=await Promise.all([api('/api/loans'),api('/api/accounts')]);state.cache.loanAccounts=accounts;root.innerHTML=`<div class="section-head"><div><h2>Loans</h2><p class="small muted">Personal and auto loan workflow from application through repayment.</p></div><button class="btn primary" onclick="applyLoanModal()">Apply for loan</button></div><div class="card-grid">${loans.map(l=>`<div class="card"><div class="split"><div><div class="account-type">${l.loan_type} LOAN #${l.id}</div><div class="balance">${money(l.amount_minor,'EGP')}</div></div>${statusBadge(l.status)}</div><div class="small muted">${l.interest_rate}% APR • ${l.term_months} months</div><div style="margin-top:14px"><div class="split small"><span>Remaining principal</span><b>${money(l.remaining_principal_minor,'EGP')}</b></div><div class="progress" style="margin-top:7px"><span style="width:${Math.max(0,Math.min(100,100-(l.remaining_principal_minor/l.amount_minor*100)))}%"></span></div></div><div class="split" style="margin-top:13px"><span class="small muted">Monthly payment</span><b>${money(l.monthly_payment_minor,'EGP')}</b></div>${l.status==='ACTIVE'?`<button class="btn full" style="margin-top:13px" onclick="payLoanModal(${l.id},${l.monthly_payment_minor})">Make payment</button>`:''}</div>`).join('')||'<div class="empty">No loans yet.</div>'}</div>`;state.cache.loans=loans;}
window.applyLoanModal=()=>{const accounts=state.cache.loanAccounts||[];openModal('Apply for a loan',`<form id="loan-form"><div class="grid-2"><div class="field"><label>Loan type</label><select name="loanType"><option>PERSONAL</option><option>AUTO</option></select></div><div class="field"><label>Amount (EGP)</label><input name="amount" type="number" min="1000" step="100" required></div></div><div class="grid-2"><div class="field"><label>Term</label><select name="termMonths"><option>12</option><option selected>24</option><option>36</option><option>48</option><option>60</option></select></div><div class="field"><label>Disbursement account</label><select name="disbursementAccountId">${accounts.filter(a=>a.currency==='EGP'&&a.status==='ACTIVE').map(a=>`<option value="${a.id}">${a.account_type} ${mask(a.account_number)}</option>`).join('')}</select></div></div><div class="field"><label>Purpose</label><textarea name="purpose" required></textarea></div><div class="callout">Personal loan: 18% APR. Auto loan: 15.5% APR. Applications enter the back-office review queue.</div><button class="btn primary full" style="margin-top:14px" data-testid="loan-submit">Submit application</button></form>`);setTimeout(()=>{const f=document.querySelector('#loan-form');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{await api('/api/loans',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();toast('Loan submitted','The application is awaiting review.');renderLoans(document.querySelector('#view'));}catch(err){toast('Application failed',err.message,'error');}}},0);};
window.payLoanModal=(id,monthly)=>{const accounts=state.cache.loanAccounts||[];openModal(`Pay loan #${id}`,`<form id="loan-pay"><div class="field"><label>From account</label><select name="accountId">${accounts.filter(a=>a.status==='ACTIVE'&&a.currency==='EGP').map(a=>`<option value="${a.id}">${mask(a.account_number)} • ${money(a.balance_minor,a.currency)}</option>`).join('')}</select></div><div class="field"><label>Payment amount</label><input name="amount" type="number" step="0.01" min="1" value="${(monthly/100).toFixed(2)}"></div><button class="btn primary full" data-testid="loan-pay-submit">Pay loan</button></form>`);setTimeout(()=>{const f=document.querySelector('#loan-pay');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{await api(`/api/loans/${id}/pay`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();toast('Loan payment completed');renderLoans(document.querySelector('#view'));}catch(err){toast('Payment failed',err.message,'error');}}},0);};

async function renderKyc(root){await refreshMe();const k=await api('/api/kyc');root.innerHTML=`<div class="section-grid"><div class="card"><div class="section-head"><div><h2>Identity & KYC</h2><p class="small muted">Customer due-diligence profile and identity-document upload.</p></div>${statusBadge(k?.status||'NOT_STARTED')}</div><form id="kyc-form"><div class="grid-2"><div class="field"><label>Date of birth</label><input name="dateOfBirth" type="date" value="${escapeHtml(k?.date_of_birth||'')}"></div><div class="field"><label>Nationality</label><input name="nationality" value="${escapeHtml(k?.nationality||'')}"></div></div><div class="field"><label>Address</label><input name="address" value="${escapeHtml(k?.address||'')}"></div><div class="grid-2"><div class="field"><label>Employment</label><input name="employment" value="${escapeHtml(k?.employment||'')}"></div><div class="field"><label>Annual income</label><input name="annualIncome" type="number" value="${k?.annual_income_minor?(k.annual_income_minor/100):''}"></div></div><div class="grid-2"><div class="field"><label>ID type</label><select name="idType"><option>NATIONAL_ID</option><option>PASSPORT</option></select></div><div class="field"><label>ID number</label><input name="idNumber" placeholder="Enter ID to resubmit"></div></div><div class="field"><label>Identity document</label><input id="kyc-file" type="file" accept="application/pdf,image/png,image/jpeg"><span class="small muted">${k?.document_name?`Stored: ${escapeHtml(k.document_name)}${k.has_document?' (downloadable)':''}`:'No document uploaded yet.'}</span></div><div class="actions">${k?.has_document?'<button class="btn" type="button" onclick="downloadKycDocument()">Download stored document</button>':''}<button class="btn primary" type="submit">Submit for review</button></div></form>${k?.reviewer_note?`<div class="callout" style="margin-top:14px"><b>Reviewer note:</b> ${escapeHtml(k.reviewer_note)}</div>`:''}</div><div class="card"><div class="section-head"><h2>Profile</h2></div><form id="profile-form"><div class="grid-2"><div class="field"><label>First name</label><input name="firstName" value="${escapeHtml(state.me.user.first_name)}"></div><div class="field"><label>Last name</label><input name="lastName" value="${escapeHtml(state.me.user.last_name)}"></div></div><div class="field"><label>Email</label><input value="${escapeHtml(state.me.user.email)}" disabled></div><div class="field"><label>Phone</label><input name="phone" value="${escapeHtml(state.me.user.phone||'')}"></div><button class="btn">Save profile</button></form></div></div>`;document.querySelector('#kyc-form').onsubmit=async e=>{e.preventDefault();try{const payload=Object.fromEntries(new FormData(e.currentTarget));delete payload[''];const file=document.querySelector('#kyc-file').files[0];if(file){if(file.size>2_000_000)throw new Error('KYC document must be 2 MB or smaller in this QA environment.');payload.documentName=file.name;payload.documentMime=file.type||'application/octet-stream';payload.documentDataB64=await fileToBase64(file);}else payload.documentName=k?.document_name||'identity-document.pdf';await api('/api/kyc',{method:'POST',body:JSON.stringify(payload)});toast('KYC submitted','Your status is now under review.');renderKyc(root);}catch(err){toast('KYC submission failed',err.message,'error');}};document.querySelector('#profile-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/profile',{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});await refreshMe();toast('Profile saved');renderShell();navigate('kyc');}catch(err){toast('Unable to save',err.message,'error');}};}
window.downloadKycDocument=async()=>{try{const r=await fetch('/api/kyc/document',{headers:{Authorization:`Bearer ${state.token}`}});if(!r.ok){const d=await r.json();throw new Error(d.error||'Download failed');}const blob=await r.blob(),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='kyc-document';a.click();URL.revokeObjectURL(u);}catch(e){toast('Document unavailable',e.message,'error');}};

async function renderNotifications(root){const rows=await api('/api/notifications');root.innerHTML=`<div class="section-head"><div><h2>Notifications</h2><p class="small muted">In-app events plus simulated email/SMS channels.</p></div></div><div class="list">${rows.map(n=>`<div class="list-item notification ${n.read_at?'':'unread'}"><div><div class="split" style="justify-content:flex-start"><div class="title">${escapeHtml(n.title)}</div><span class="badge">${escapeHtml(n.channel)}</span></div><div class="meta">${escapeHtml(n.message)} • ${date(n.created_at)}</div></div>${n.read_at?'':`<button class="btn small-btn" onclick="markRead(${n.id})">Mark read</button>`}</div>`).join('')||'<div class="empty">No notifications.</div>'}</div>`;}
window.markRead=async id=>{await api(`/api/notifications/${id}/read`,{method:'POST',body:'{}'});await refreshMe();renderNotifications(document.querySelector('#view'));};

async function renderSecurity(root){root.innerHTML=`<div class="section-grid"><div class="card"><div class="section-head"><h2>Password</h2></div><form id="password-form"><div class="field"><label>Current password</label><input name="currentPassword" type="password" required></div><div class="field"><label>New password</label><input name="newPassword" type="password" minlength="8" required></div><button class="btn primary">Change password</button></form></div><div class="card"><div class="section-head"><h2>Security controls</h2></div><div class="list"><div class="list-item"><div><div class="title">Multi-factor authentication</div><div class="meta">Required for seeded accounts</div></div><span class="badge good">ENABLED</span></div><div class="list-item"><div><div class="title">Session management</div><div class="meta">8-hour session or 30-day remembered device</div></div><span class="badge info">ACTIVE</span></div><div class="list-item"><div><div class="title">Login lockout</div><div class="meta">5 failed attempts → 15 minute lock</div></div><span class="badge good">ENFORCED</span></div></div></div></div>`;document.querySelector('#password-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/auth/change-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast('Password changed','Other password-reset flows remain available from sign-in.');e.currentTarget.reset();}catch(err){toast('Password change failed',err.message,'error');}};}

// ---------------- Back office ----------------
function roleHint(){return `<div class="role-banner">Signed in as <b>${escapeHtml(state.me.user.role)}</b>. Permissions are enforced by the API: support/auditor roles are read-only, employee can review KYC, manager can operate financial controls, and admin can also manage roles.</div>`;}
async function renderAdminDashboard(root){const m=await api('/api/admin/dashboard');root.innerHTML=`${roleHint()}<div class="hero-card"><div class="badge info">BACK-OFFICE CONTROL CENTER</div><h2>Bank operations & risk</h2><p>Review customer state, KYC, financial operations, fraud alerts and immutable audit activity from a role-controlled operations workspace.</p></div><div class="metric-row" style="margin-top:16px"><div class="card kpi"><div class="label">Customers</div><div class="value">${m.customers}</div></div><div class="card kpi"><div class="label">Active accounts</div><div class="value">${m.activeAccounts}</div></div><div class="card kpi"><div class="label">Pending KYC</div><div class="value">${m.pendingKyc}</div></div><div class="card kpi"><div class="label">Open fraud</div><div class="value">${m.openFraud}</div></div><div class="card kpi"><div class="label">Pending loans</div><div class="value">${m.pendingLoans}</div></div><div class="card kpi"><div class="label">Transfer volume</div><div class="value" style="font-size:19px">${money(m.transferVolumeMinor,'EGP')}</div></div></div><div class="section-grid" style="margin-top:16px"><div class="card"><div class="section-head"><h3>Operational queues</h3></div><div class="list"><div class="list-item"><div><div class="title">KYC review</div><div class="meta">Pending identity-verification decisions</div></div><button class="btn small-btn" onclick="navigate('admin-kyc')">Open</button></div><div class="list-item"><div><div class="title">Loan underwriting</div><div class="meta">Applications awaiting decision</div></div><button class="btn small-btn" onclick="navigate('admin-loans')">Open</button></div><div class="list-item"><div><div class="title">Fraud monitoring</div><div class="meta">Rule-based suspicious transaction alerts</div></div><button class="btn small-btn" onclick="navigate('admin-fraud')">Open</button></div></div></div><div class="card"><div class="section-head"><h3>Control principles</h3></div><div class="callout">Every sensitive staff operation records actor, action, entity, result, timestamp and metadata in the audit trail. Auditor access is intentionally read-only.</div></div></div>`;}

async function renderAdminCustomers(root){const rows=await api('/api/admin/customers');root.innerHTML=`${roleHint()}<div class="section-head"><div><h2>Customer directory</h2><p class="small muted">Search customer profiles and inspect linked banking state.</p></div><input class="input search" id="customer-search" placeholder="Search name or email" oninput="filterCustomers()"></div><div class="card"><div class="table-wrap"><table class="table" id="customer-table" data-testid="customer-table"><thead><tr><th>Name</th><th>Email</th><th>KYC</th><th>User status</th><th>Created</th><th></th></tr></thead><tbody>${rows.map(u=>`<tr data-search="${escapeHtml(`${u.first_name} ${u.last_name} ${u.email}`.toLowerCase())}"><td><b>${escapeHtml(u.first_name)} ${escapeHtml(u.last_name)}</b></td><td>${escapeHtml(u.email)}</td><td>${statusBadge(u.kyc_status||'NOT_STARTED')}</td><td>${statusBadge(u.status)}</td><td>${date(u.created_at)}</td><td><button class="btn small-btn" onclick="inspectCustomer(${u.id})">Inspect</button></td></tr>`).join('')}</tbody></table></div></div>`;}
window.filterCustomers=()=>{const q=(document.querySelector('#customer-search')?.value||'').toLowerCase();document.querySelectorAll('#customer-table tbody tr').forEach(r=>r.classList.toggle('hidden',!r.dataset.search.includes(q)));};
window.inspectCustomer=async id=>{try{const x=await api(`/api/admin/customers/${id}`);openModal(`${x.snapshot.user.first_name} ${x.snapshot.user.last_name}`,`<div class="kpi-grid"><div class="card kpi"><div class="label">Accounts</div><div class="value">${x.snapshot.accounts.length}</div></div><div class="card kpi"><div class="label">Cards</div><div class="value">${x.snapshot.cards.length}</div></div><div class="card kpi"><div class="label">Transfers</div><div class="value">${x.transfers.length}</div></div><div class="card kpi"><div class="label">Loans</div><div class="value">${x.loans.length}</div></div></div><div class="callout">${escapeHtml(x.snapshot.user.email)} • KYC ${escapeHtml(x.kyc?.status||'NOT_STARTED')}</div><div class="table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>Account</th><th>Type</th><th>Currency</th><th>Balance</th><th>Status</th></tr></thead><tbody>${x.snapshot.accounts.map(a=>`<tr><td class="mono">${mask(a.account_number)}</td><td>${a.account_type}</td><td>${a.currency}</td><td>${money(a.balance_minor,a.currency)}</td><td>${statusBadge(a.status)}</td></tr>`).join('')}</tbody></table></div>`,{large:true});}catch(e){toast('Unable to inspect customer',e.message,'error');}};

async function renderAdminKyc(root){const rows=await api('/api/admin/kyc');root.innerHTML=`${roleHint()}<div class="card"><div class="section-head"><h2>KYC queue</h2><span class="small muted">${rows.length} profiles</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Status</th><th>ID type</th><th>Nationality</th><th>Employment</th><th>Document</th><th>Updated</th><th></th></tr></thead><tbody>${rows.map(k=>`<tr><td><b>${escapeHtml(k.first_name)} ${escapeHtml(k.last_name)}</b><br><span class="muted small">${escapeHtml(k.email)}</span></td><td>${statusBadge(k.status)}</td><td>${escapeHtml(k.id_type||'—')}</td><td>${escapeHtml(k.nationality||'—')}</td><td>${escapeHtml(k.employment||'—')}</td><td>${k.has_document?`<button class="btn small-btn" onclick="adminDownloadKyc(${k.id},'${escapeHtml(k.document_name||'document')}')">Download</button>`:`<span class="muted">${escapeHtml(k.document_name||'—')}</span>`}</td><td>${date(k.updated_at)}</td><td><button class="btn small-btn" onclick="reviewKycModal(${k.id},'${escapeHtml(k.first_name)} ${escapeHtml(k.last_name)}')">Review</button></td></tr>`).join('')}</tbody></table></div></div>`;}
window.adminDownloadKyc=async(id,name)=>{try{const r=await fetch(`/api/admin/kyc/${id}/document`,{headers:{Authorization:`Bearer ${state.token}`}});if(!r.ok){const d=await r.json();throw new Error(d.error||'Download failed');}const blob=await r.blob(),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();URL.revokeObjectURL(u);}catch(e){toast('Document unavailable',e.message,'error');}};
window.reviewKycModal=(id,name)=>{openModal(`Review KYC — ${name}`,`<form id="kyc-review"><div class="field"><label>Decision</label><select name="status"><option>VERIFIED</option><option>NEEDS_MORE_INFORMATION</option><option>REJECTED</option><option>SUSPENDED</option></select></div><div class="field"><label>Reviewer note</label><textarea name="note"></textarea></div><button class="btn primary full">Submit decision</button></form>`);setTimeout(()=>{const f=document.querySelector('#kyc-review');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{await api(`/api/admin/kyc/${id}/review`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();toast('KYC reviewed');renderAdminKyc(document.querySelector('#view'));}catch(err){toast('Review denied',err.message,'error');}}},0);};

async function renderAdminAccounts(root){const rows=await api('/api/admin/accounts');root.innerHTML=`${roleHint()}<div class="card"><div class="section-head"><h2>Account operations</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Account</th><th>Type</th><th>Balance</th><th>Daily limit</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td>${escapeHtml(a.first_name)} ${escapeHtml(a.last_name)}<br><span class="small muted">${escapeHtml(a.email)}</span></td><td class="mono">${mask(a.account_number)} • ${a.currency}</td><td>${a.account_type}</td><td>${money(a.balance_minor,a.currency)}</td><td>${money(a.daily_limit_minor,a.currency)}</td><td>${statusBadge(a.status)}</td><td class="right">${a.status==='ACTIVE'?`<button class="btn small-btn warn" onclick="adminAccountAction(${a.id},'freeze')">Freeze</button> <button class="btn small-btn" onclick="adminAccountAction(${a.id},'dormant')">Dormant</button>`:a.status==='FROZEN'?`<button class="btn small-btn" onclick="adminAccountAction(${a.id},'unfreeze')">Unfreeze</button>`:a.status==='DORMANT'?`<button class="btn small-btn" onclick="adminAccountAction(${a.id},'activate')">Activate</button>`:''}<button class="btn small-btn" onclick="adminLimitModal(${a.id},${a.daily_limit_minor/100},'${a.currency}')">Limit</button></td></tr>`).join('')}</tbody></table></div></div>`;}
window.adminAccountAction=async(id,action)=>{try{await api(`/api/admin/accounts/${id}/${action}`,{method:'POST',body:'{}'});toast('Account updated',action.toUpperCase());renderAdminAccounts(document.querySelector('#view'));}catch(e){toast('Operation denied',e.message,'error');}};window.adminLimitModal=(id,current,currency)=>{openModal('Change daily transfer limit',`<form id="limit-form"><div class="field"><label>Daily limit (${currency})</label><input name="dailyLimit" type="number" step="0.01" value="${current}" required></div><button class="btn primary full">Update limit</button></form>`);setTimeout(()=>{const f=document.querySelector('#limit-form');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{await api(`/api/admin/accounts/${id}/limit`,{method:'POST',body:JSON.stringify({dailyLimit:new FormData(e.currentTarget).get('dailyLimit')})});closeModal();toast('Limit updated');renderAdminAccounts(document.querySelector('#view'));}catch(err){toast('Operation denied',err.message,'error');}}},0);};

async function renderAdminTransfers(root){const rows=await api('/api/admin/transfers');root.innerHTML=`${roleHint()}<div class="card"><div class="section-head"><h2>Transfer operations</h2><span class="small muted">Reversal is permission-controlled and creates compensating ledger entries.</span></div>${tableTransfers(rows,true)}</div>`;}
window.adminReverseTransfer=async id=>{if(!confirm('Reverse this completed transfer? This creates compensating ledger entries.'))return;try{await api(`/api/admin/transfers/${id}/reverse`,{method:'POST',body:'{}'});toast('Transfer reversed');renderAdminTransfers(document.querySelector('#view'));}catch(e){toast('Reversal denied',e.message,'error');}};

async function renderAdminLoans(root){const rows=await api('/api/admin/loans');root.innerHTML=`${roleHint()}<div class="card"><div class="section-head"><h2>Loan underwriting</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Type</th><th>Amount</th><th>APR</th><th>Term</th><th>Monthly</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(l=>`<tr><td>${escapeHtml(l.first_name)} ${escapeHtml(l.last_name)}<br><span class="small muted">${escapeHtml(l.email)}</span></td><td>${l.loan_type}</td><td>${money(l.amount_minor,'EGP')}</td><td>${l.interest_rate}%</td><td>${l.term_months} mo</td><td>${money(l.monthly_payment_minor,'EGP')}</td><td>${statusBadge(l.status)}</td><td>${['SUBMITTED','UNDER_REVIEW'].includes(l.status)?`<button class="btn small-btn" onclick="reviewLoanModal(${l.id})">Review</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`;}
window.reviewLoanModal=id=>{openModal(`Review loan #${id}`,`<form id="loan-review"><div class="field"><label>Decision</label><select name="decision"><option>APPROVED</option><option>REJECTED</option></select></div><div class="field"><label>Underwriter note</label><textarea name="note"></textarea></div><div class="callout warn">Approving immediately disburses the loan amount to the configured customer account and creates a ledger credit.</div><button class="btn primary full" style="margin-top:14px">Submit decision</button></form>`);setTimeout(()=>{const f=document.querySelector('#loan-review');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{await api(`/api/admin/loans/${id}/review`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();toast('Loan reviewed');renderAdminLoans(document.querySelector('#view'));}catch(err){toast('Review denied',err.message,'error');}}},0);};

async function renderAdminFraud(root){const rows=await api('/api/admin/fraud');root.innerHTML=`${roleHint()}<div class="card"><div class="section-head"><h2>Fraud alerts</h2><span class="small muted">Large-transfer, velocity and failed-transfer rules</span></div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Rule</th><th>Severity</th><th>Customer</th><th>Transfer</th><th>Description</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(f=>`<tr><td class="mono">${f.rule_code}</td><td>${statusBadge(f.severity)}</td><td>${escapeHtml(f.email||'—')}</td><td class="mono">${escapeHtml(f.transfer_reference||'—')}</td><td>${escapeHtml(f.description)}</td><td>${statusBadge(f.status)}</td><td><button class="btn small-btn" onclick="fraudReviewModal(${f.id},'${f.status}')">Update</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No fraud alerts yet. Large or rapid transfers will generate alerts.</div>'}</div>`;}
window.fraudReviewModal=(id,current)=>{openModal(`Fraud alert #${id}`,`<form id="fraud-review"><div class="field"><label>Status</label><select name="status">${['OPEN','INVESTIGATING','CLEARED','CONFIRMED'].map(s=>`<option ${s===current?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Resolution note</label><textarea name="note"></textarea></div><button class="btn primary full">Update case</button></form>`);setTimeout(()=>{const f=document.querySelector('#fraud-review');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{await api(`/api/admin/fraud/${id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();toast('Fraud case updated');renderAdminFraud(document.querySelector('#view'));}catch(err){toast('Update denied',err.message,'error');}}},0);};

async function renderAdminAudit(root){const rows=await api('/api/admin/audit');root.innerHTML=`${roleHint()}<div class="card"><div class="section-head"><div><h2>Audit trail</h2><p class="small muted">Append-only record of sensitive customer and staff actions.</p></div><input class="input search" id="audit-search" placeholder="Search actor, action, entity, IP, metadata" oninput="filterAudit()"></div><div class="table-wrap"><table class="table" id="audit-table" data-testid="audit-table"><thead><tr><th>Timestamp</th><th>Actor</th><th>Action</th><th>Entity</th><th>Result</th><th>IP</th><th>Metadata</th></tr></thead><tbody>${rows.map(a=>`<tr data-search="${escapeHtml(`${a.actor_email||''} ${a.action} ${a.entity_type} ${a.entity_id||''} ${a.ip_address||''} ${a.metadata_json||''}`.toLowerCase())}"><td>${date(a.created_at)}</td><td>${escapeHtml(a.actor_email||`User #${a.actor_user_id||'system'}`)}</td><td class="mono">${escapeHtml(a.action)}</td><td>${escapeHtml(a.entity_type)} <span class="muted">${escapeHtml(a.entity_id||'')}</span></td><td>${statusBadge(a.result)}</td><td class="mono">${escapeHtml(a.ip_address||'—')}</td><td class="mono small">${escapeHtml((a.metadata_json||'{}').slice(0,100))}</td></tr>`).join('')}</tbody></table></div></div>`;}
window.filterAudit=()=>{const q=(document.querySelector('#audit-search')?.value||'').toLowerCase();document.querySelectorAll('#audit-table tbody tr').forEach(r=>r.classList.toggle('hidden',!r.dataset.search.includes(q)));};

async function renderAdminUsers(root){try{const rows=await api('/api/admin/users');root.innerHTML=`${roleHint()}<div class="card"><div class="section-head"><h2>Users & roles</h2><span class="small muted">Admin only</span></div><div class="table-wrap"><table class="table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Email verified</th><th>MFA</th><th>Created</th><th></th></tr></thead><tbody>${rows.map(u=>`<tr><td><b>${escapeHtml(u.first_name)} ${escapeHtml(u.last_name)}</b><br><span class="small muted">${escapeHtml(u.email)}</span></td><td>${statusBadge(u.role)}</td><td>${statusBadge(u.status)}</td><td>${u.email_verified?'YES':'NO'}</td><td>${u.mfa_enabled?'ON':'OFF'}</td><td>${date(u.created_at)}</td><td><button class="btn small-btn" onclick="roleModal(${u.id},'${u.role}')">Change role</button></td></tr>`).join('')}</tbody></table></div></div>`;}catch(e){root.innerHTML=`${roleHint()}<div class="callout danger"><b>Admin-only module.</b><br>${escapeHtml(e.message)}</div>`;}}
window.roleModal=(id,current)=>{openModal('Change user role',`<form id="role-form"><div class="field"><label>Role</label><select name="role">${['CUSTOMER','SUPPORT','AUDITOR','EMPLOYEE','MANAGER','ADMIN'].map(r=>`<option ${r===current?'selected':''}>${r}</option>`).join('')}</select></div><div class="callout warn">Role changes take effect on the next API request and are written to the audit trail.</div><button class="btn primary full" style="margin-top:14px">Change role</button></form>`);setTimeout(()=>{const f=document.querySelector('#role-form');if(!f)return;f.onsubmit=async e=>{e.preventDefault();try{await api(`/api/admin/users/${id}/role`,{method:'POST',body:JSON.stringify({role:new FormData(e.currentTarget).get('role')})});closeModal();toast('Role changed');renderAdminUsers(document.querySelector('#view'));}catch(err){toast('Role change denied',err.message,'error');}}},0);};

bootstrap();
